// ============================================================================
// HIGH-PRECISION WGS84 EQUIRECTANGULAR WORLD MAP & CARTOGRAPHIC PROJECTION
// Derived from Natural Earth 110m Admin-0 Countries, Admin-1 State Boundaries,
// and Major Inland Lakes, mathematically locked to the 1200x560 SVG canvas.
// ============================================================================

export const MAP_PROJECTION_BOUNDS = {
  "minLon": -168,
  "maxLon": 190,
  "minLat": -56,
  "maxLat": 74,
  "padX": 24,
  "padY": 20,
  "width": 1200,
  "height": 560
};

/**
 * Projects real-world WGS84 (latitude, longitude) degrees to exact (x, y)
 * coordinates on the 1200x560 tactical world map SVG canvas.
 */
export function projectLatLon(lat, lon) {
  const { minLon, maxLon, minLat, maxLat, padX, padY, width, height } =
    MAP_PROJECTION_BOUNDS;
  const w = width - padX * 2;
  const h = height - padY * 2;
  let normLon = Number(lon);
  if (normLon < minLon) normLon += 360;
  const clampedLon = Math.max(minLon, Math.min(maxLon, normLon));
  const clampedLat = Math.max(minLat, Math.min(maxLat, Number(lat)));
  const x = padX + ((clampedLon - minLon) / (maxLon - minLon)) * w;
  const y = padY + ((maxLat - clampedLat) / (maxLat - minLat)) * h;
  return {
    x: Number(x.toFixed(1)),
    y: Number(y.toFixed(1)),
  };
}

/**
 * Inverse projection: converts SVG (x, y) coordinates on the 1200x560 canvas
 * back into real-world WGS84 (lat, lon) degrees for the live GPS HUD readout.
 */
export function unprojectSvgPoint(x, y) {
  const { minLon, maxLon, minLat, maxLat, padX, padY, width, height } =
    MAP_PROJECTION_BOUNDS;
  const w = width - padX * 2;
  const h = height - padY * 2;
  let lon = minLon + ((x - padX) / w) * (maxLon - minLon);
  if (lon > 180) lon -= 360;
  const lat = maxLat - ((y - padY) / h) * (maxLat - minLat);
  return {
    lat: Number(Math.max(-90, Math.min(90, lat)).toFixed(2)),
    lon: Number(Math.max(-180, Math.min(180, lon)).toFixed(2)),
  };
}

/**
 * Formats (lat, lon) degrees into standard cartographic GPS notation
 * e.g. "41.26°N, 95.86°W"
 */
export function formatLatLon(lat, lon) {
  const latDir = lat >= 0 ? 'N' : 'S';
  const lonDir = lon >= 0 ? 'E' : 'W';
  return `${Math.abs(Number(lat)).toFixed(2)}°${latDir}, ${Math.abs(Number(lon)).toFixed(2)}°${lonDir}`;
}

/**
 * Computes exact Haversine Great-Circle distance (km) between two WGS84 coordinates.
 */
export function calculateGreatCircleKm(lat1, lon1, lat2, lon2) {
  const R = 6371; // Earth mean radius in km
  const toRad = (deg) => (deg * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLon = toRad(lon2 - lon1);
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRad(lat1)) *
      Math.cos(toRad(lat2)) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return Math.round(R * c);
}

